{
    if (m_draft == text)
        return;
    m_draft = text;
    if (!m_config.managed_root.empty()) {
        m_document.set_draft(text);
        commit();
    }
    write_recovery_meta();
}

void ProjectPersistence::write_recovery_meta() const
{
    const std::string recovery = recovery_dir();
    if (recovery.empty())
